cd /work/workspace && python3 - <<'EOF'
import re,io,collections,os
allowed_top={'721','731','752','7872','1202','83'}
for f in ['deliverable/opinion.md','deliverable/STATUS.md','deliverable/QUESTIONS.md','deliverable/agreements_required.md']:
    txt=io.open(f,encoding='utf-8').read()
    nums=collections.Counter(m.group(1) for m in re.finditer(r'§(\d+[A-Za-z]?)',txt))
    bad={k:v for k,v in nums.items() if k not in allowed_top}
    print(f, dict(sorted(nums.items())), "| OUT-OF-LIBRARY:", bad)
    # table column check
    lines=txt.split('\n'); bad_rows=[]
    for i,l in enumerate(lines):
        if l.strip().startswith('|'):
            # count unescaped pipes
            n=len(re.findall(r'(?<!\\)\|',l))
            bad_rows.append((i+1,n))
    # group consecutive table blocks
    blocks=[];cur=[]
    for i,l in enumerate(lines):
        if l.strip().startswith('|'): cur.append((i+1,len(re.findall(r'(?<!\\)\|',l))))
        else:
            if cur: blocks.append(cur); cur=[]
    if cur: blocks.append(cur)
    for b in blocks:
        counts={n for _,n in b}
        if len(counts)>1:
            print("  !! inconsistent table columns in",f,"starting line",b[0][0],counts, [x for x in b if x[1]!=max(set(n for _,n in b),key=[q[1] for q in b].count)])
print("TABLE CHECK DONE")
EOF

